import{_ as n,o as a,c as i,a5 as t}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"异常处理机制","description":"程序运行时会遇到错误——除零、访问违例、非法指令。Windows 通过异常处理机制来应对这些错误。逆向里，异常处理既是「理解程序如何容错」的钥匙，也是「识别反调试手段」的线索。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/03-windows-internals/chapter-05-exception-handling.md","filePath":"reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"}'),r={name:"reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"};function s(d,e,l,c,o,g){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="异常处理机制" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">异常处理机制 <a class="header-anchor" href="#异常处理机制" aria-label="Permalink to &quot;异常处理机制&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">程序运行时会遇到错误——除零、访问违例、非法指令。Windows 通过异常处理机制来应对这些错误。逆向里，异常处理既是「理解程序如何容错」的钥匙，也是「识别反调试手段」的线索。</p><h2 id="_1-什么是异常" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">1. 什么是异常 <a class="header-anchor" href="#_1-什么是异常" aria-label="Permalink to &quot;1. 什么是异常&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">异常是 CPU 或程序在运行时发出的「出错信号」。常见的几种：</p><table tabindex="0"><thead data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><tr data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><th style="text-align:left;">异常</th><th style="text-align:left;">触发场景</th></tr></thead><tbody data-src-line="12" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><tr data-src-line="12" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><td style="text-align:left;">访问违例（Access Violation）</td><td style="text-align:left;">读写未映射或无权访问的内存</td></tr><tr data-src-line="13" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><td style="text-align:left;">除零异常</td><td style="text-align:left;">整数除以 0</td></tr><tr data-src-line="14" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><td style="text-align:left;">断点异常（<code>INT 3</code>）</td><td style="text-align:left;">执行到 <code>0xCC</code>，调试器靠它下软件断点</td></tr><tr data-src-line="15" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><td style="text-align:left;">单步异常</td><td style="text-align:left;">单步执行时每走一条指令触发一次</td></tr><tr data-src-line="16" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><td style="text-align:left;">非法指令</td><td style="text-align:left;">执行了无效的机器码</td></tr></tbody></table><p data-src-line="18" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">注意，<code>INT 3</code> 断点异常和单步异常也走异常处理机制——这解释了为什么调试器能截获断点和单步，也解释了为什么程序能反过来利用异常检测调试器。</p><h2 id="_2-两种历史机制-seh-与表驱动" tabindex="-1" data-src-line="20" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">2. 两种历史机制：SEH 与表驱动 <a class="header-anchor" href="#_2-两种历史机制-seh-与表驱动" aria-label="Permalink to &quot;2. 两种历史机制：SEH 与表驱动&quot;">​</a></h2><p data-src-line="22" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">Windows 的异常处理有两种历史机制：</p><ul data-src-line="24" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><li data-src-line="24" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><strong>x86 的 SEH（Structured Exception Handling，结构化异常处理）</strong>：在栈上维护一个异常处理链表（<code>fs:[0]</code> 指向链表头），每个 <code>try</code> 块对应链表上的一个节点。异常发生时，系统遍历链表找处理函数。</li><li data-src-line="25" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><strong>x64 的异常处理</strong>：改为<strong>基于表</strong>。编译器在 <code>.pdata</code> 节里生成展开信息（unwind info），异常处理函数不再挂栈上链表，而是查表定位。</li></ul><p data-src-line="27" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">对逆向的实际影响：在 x64 反汇编里，你<strong>不会再看到</strong> x86 那种 <code>push handler; mov fs:[0], esp</code> 的经典 SEH 安装序列。如果看到程序手动操作异常处理、或故意触发异常来跳转，那是花指令或反调试的手段。</p><h2 id="_3-异常如何被处理" tabindex="-1" data-src-line="29" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">3. 异常如何被处理 <a class="header-anchor" href="#_3-异常如何被处理" aria-label="Permalink to &quot;3. 异常如何被处理&quot;">​</a></h2><p data-src-line="31" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">以 x64 为例，异常发生时的处理流程大致是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>异常发生 → CPU 查 IDT（中断描述符表）进入内核</span></span>
<span class="line"><span>→ 内核把异常分发给当前线程的异常处理链</span></span>
<span class="line"><span>→ 先看有没有调试器（调试器有优先处理权）</span></span>
<span class="line"><span>→ 没有调试器，或调试器不处理 → 查表找用户态异常处理函数</span></span>
<span class="line"><span>→ 找到就执行，找不到就终止进程</span></span></code></pre></div><p data-src-line="41" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">这里有个对逆向很关键的点：<strong>调试器有异常处理的优先权</strong>。程序抛出的异常，调试器先看到，可以选择「处理掉」或「转交给程序」。所以程序可以故意抛异常，试探「异常有没有被调试器截获」——这本身就是一个反调试信号。</p><h2 id="_4-异常与反调试的关系" tabindex="-1" data-src-line="43" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">4. 异常与反调试的关系 <a class="header-anchor" href="#_4-异常与反调试的关系" aria-label="Permalink to &quot;4. 异常与反调试的关系&quot;">​</a></h2><p data-src-line="45" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">程序故意抛异常，是检测调试器的一种手段：</p><ul data-src-line="47" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><li data-src-line="47" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">如果程序在调试器里运行，异常会被调试器截获，程序可能检测到「异常没有被正常处理」。</li><li data-src-line="48" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">程序也可能自己安装异常处理函数，在函数里检查调试寄存器、检查是否有调试器痕迹。</li></ul><p data-src-line="50" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">所以，<a href="./../07-packing/chapter-03-virtualization-anti-debugging.html">反调试与反静态分析</a>里很多技巧都建立在异常机制上。理解异常如何被分发，才能理解这些反调试手段为什么有效、如何绕过。</p><h2 id="_5-逆向中如何看异常处理" tabindex="-1" data-src-line="52" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">5. 逆向中如何看异常处理 <a class="header-anchor" href="#_5-逆向中如何看异常处理" aria-label="Permalink to &quot;5. 逆向中如何看异常处理&quot;">​</a></h2><p data-src-line="54" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">分析程序时，关注异常处理的几个角度：</p><ul data-src-line="56" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><li data-src-line="56" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><strong>看导入表</strong>：程序导入了 <code>SetUnhandledExceptionFilter</code>、<code>AddVectoredExceptionHandler</code> 等，说明它主动安装了异常处理。</li><li data-src-line="57" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><strong>看 <code>.pdata</code> 节</strong>：x64 程序的展开信息在这里，反汇编器据此还原 <code>try/catch</code> 结构。</li><li data-src-line="58" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><strong>警惕「异常驱动的控制流」</strong>：如果程序故意抛异常、在异常处理函数里跳转到别处，这是混淆或反调试的信号。</li></ul><hr><blockquote data-src-line="62" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md"><p data-src-line="62" data-src-file="reverse-engineering/03-windows-internals/chapter-05-exception-handling.md">本章建立的是异常处理的机制：异常是运行时错误信号，x86 用栈上链表、x64 用表驱动处理；调试器对异常有优先处理权，这既是调试的基础，也是反调试的切入点。至此 Windows 底层机制告一段落。下一阶段进入<a href="./../05-static-analysis/chapter-01-basics.html">静态分析</a>。</p></blockquote>`,23)])])}const w=n(r,[["render",s]]);export{h as __pageData,w as default};
